<?php
if (!defined("SUAVE_RAIZ")) { http_response_code(404); exit; } use Suave\Interfaz as V;use Suave\Numeros as N;
$s=(new Suave\Conciliador($db))->summary($month);$selectedState=(string)($_GET['estado']??'');if(!in_array($selectedState,['Pendiente','Resuelto','Coincide'],true))$selectedState='';
$runId=(int)($_GET['comparacion_id']??$period['comparacion_id']??0);$run=$runId?$db->one('SELECT co.*,r.numero AS reporte_numero,r.modalidad FROM comparaciones co JOIN reportes r ON r.id=co.reporte_id WHERE co.id=? AND co.mes=?',[$runId,$month]):null;
$historical=$run && (int)$run['id']!==(int)$period['comparacion_id'];
$cases=$run?$db->all('SELECT * FROM casos WHERE comparacion_id=? AND fusionado_en IS NULL ORDER BY id',[$run['id']]):[];
$cases=array_filter($cases,fn($c)=>($branch===''||$c['sucursal_codigo']===$branch)&&($selectedState===''||$c['estado']===$selectedState));
$noteMap=array_column($db->all('SELECT v.id,e.id AS entrega_id,e.referencia,v.numero,v.folio FROM entrega_versiones v JOIN entregas e ON e.id=v.entrega_id WHERE v.mes=?',[$month]),null,'id');
$rowMap=$run?array_column($db->all('SELECT * FROM reporte_filas WHERE reporte_id=?',[$run['reporte_id']]),null,'id'):[];
?>
<div class="page-heading"><div><h1>Conciliación</h1><p><?=V::h(ucfirst(V::monthLabel($month)))?> · Compara las notas registradas con el reporte del cliente.</p></div><?=$w->link('Historial de comparaciones','conciliacion',['historial'=>1])?></div>
<?=$w->filters('conciliacion',$allBranches,[V::select('Estado','estado',[''=>'Todos','Pendiente'=>'Pendientes','Resuelto'=>'Resueltos','Coincide'=>'Coincidencias'],$selectedState)])?>
<?php if(isset($_GET['historial'])):?>
<div class="table-wrap"><table><thead><tr><th>Comparación</th><th>Fecha</th><th>Reporte</th><th>Consulta</th></tr></thead><tbody><?php foreach($db->all('SELECT co.*,r.numero FROM comparaciones co JOIN reportes r ON r.id=co.reporte_id WHERE co.mes=? ORDER BY co.id DESC',[$month]) as $co):?><tr><td>#<?=$co['id']?> <?=(int)$period['comparacion_id']===(int)$co['id']?V::badge('En uso'):''?></td><td><?=V::h($co['creado_en'])?></td><td>v<?=$co['numero']?></td><td><?=$w->link('Consultar','conciliacion',['comparacion_id'=>$co['id']],'text-link')?></td></tr><?php endforeach?></tbody></table></div><?php endif?>
<?php if(!$s['report']):?><?=V::empty('Falta el reporte del cliente','Las entregas están disponibles, pero todavía no hay una fuente del cliente para comparar.',$w->link('Preparar reporte','reportes',[],'button primary'))?><?php return;endif?>
<?php if($historical):?><div class="notice">Consulta histórica de la comparación #<?=$run['id']?>. <?=$w->link('Volver a la vigente','conciliacion',[],'text-link')?></div><?php endif?>
<div class="section-heading"><p class="hint">Reporte en esta comparación: v<?=$run['reporte_numero']??$s['report']['numero']?> · <?=($run['modalidad']??$s['report']['modalidad'])==='detalle'?'Detalle de entregas':'Totales por sucursal'?></p><form method="post"><?=V::protect('comparar')?><?=V::hidden('mes',$month)?><button class="button" type="submit">Actualizar comparación</button></form></div>
<?php if(($run['modalidad']??$s['report']['modalidad'])==='totales'):?><div class="notice">Se comparan totales de sucursal del mes completo. La fuente no permite confirmar cantidades, precios ni notas individuales.</div><?php elseif(!$params['folio_compartido']):?><p class="hint">El enlace automático por folio está desactivado hasta comprobar que exista en ambas fuentes. Los importes iguales también requieren confirmar su correspondencia.</p><?php endif?>
<?php if(!$cases):?><?=V::empty('No hay casos con estos filtros','Consulta otro estado o revisa el alcance del mes.')?><?php else:?>
<div class="table-wrap"><table><thead><tr><th>Caso / Sucursal</th><th>Nota SUAVE</th><th>Reporte cliente</th><th>SUAVE</th><th>Excel</th><th>Diferencia</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach($cases as $c):$versions=Suave\Datos::decode($c['versiones_json']);$rowIds=Suave\Datos::decode($c['filas_json']);?><tr><td><strong>C-<?=$c['id']?></strong><small><?=V::h($c['sucursal_codigo'])?></small></td><td><?php if($versions):foreach($versions as $vid):$n=$noteMap[$vid]??null;if($n):?><?=$w->link($n['referencia'].' v'.$n['numero'],'ver_entrega',['id'=>$n['entrega_id'],'version'=>$n['numero'],'volver'=>'conciliacion'],'text-link')?><?php endif;endforeach;else:?>Sin nota<?php endif?></td><td><?php if($rowIds):foreach($rowIds as $rid):$r=$rowMap[$rid]??null;if($r):?><small><?=V::h($r['hoja'].' · fila '.$r['fila'])?></small><?php endif;endforeach;else:?>Sin contraparte<?php endif?></td><td class="amount"><?=N::currency((int)$c['suave_centavos'])?></td><td class="amount"><?=$c['excel_centavos']===null?'Sin contraparte':N::currency((int)$c['excel_centavos'])?></td><td class="amount"><?=$c['excel_centavos']===null?'Pendiente':N::currency((int)$c['suave_centavos']-(int)$c['excel_centavos'])?></td><td><?=V::badge($c['estado'])?><small><?=V::h($c['tipo'])?></small></td><td><?=$w->link($c['estado']==='Pendiente'?'Revisar caso':'Consultar','caso',['id'=>$c['id']],'text-link')?></td></tr><?php endforeach?></tbody></table></div><?php endif?>
